# %%
# セル2：HTTPサーバーを起動します。再実行時は前のサーバーを停止します。
from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler
from functools import partial
import threading
if "GAME_SERVER" in globals():
    GAME_SERVER.shutdown()
    GAME_SERVER.server_close()
    GAME_THREAD.join(timeout=2)
class GameHandler(SimpleHTTPRequestHandler):
    def log_message(self, format, *args):
        pass
GAME_SERVER = ThreadingHTTPServer(("0.0.0.0", 0), partial(GameHandler, directory=str(GAME_DIR)))
GAME_PORT = GAME_SERVER.server_address[1]
GAME_THREAD = threading.Thread(target=GAME_SERVER.serve_forever, daemon=True)
GAME_THREAD.start()
print(f"ゲームサーバーを起動しました（ポート {GAME_PORT}）。次のセルを実行してください。")


# %%
# セル3：Google Colabの出力欄にゲーム画面を表示します。
from google.colab import output
output.serve_kernel_port_as_iframe(GAME_PORT, height=850)
print("ゲーム画面を一度クリックすると、キーボードで操作できます。")
